"""paper_2.0/srw/main_v3.tex = main_v2.tex + X3 (Gemma-2-9B-it). Writes new files only: paper_2.0/numbers_x3.tex, paper_2.0/srw/main_v3.tex,
results/x3/paper_srw_v3_changes.csv. Every number is a macro from results/x3 CSVs; every edit is an exact replacement that occurs once in v2."""
import re
from pathlib import Path

import pandas as pd

REPO = Path(__file__).resolve().parents[1]
P = REPO / "paper_2.0"
C = pd.read_csv(REPO / "results/x3/coefficients.csv"); Q = pd.read_csv(REPO / "results/x3/questions.csv")
G = pd.read_csv(REPO / "results/x3/pilot_checks.csv").set_index("check")
s = lambda v: f"{v:+.2f}".replace("+", "$+$").replace("-", "$-$")
ci = lambda r, k="obscurity": f"[{s(r[k + '_lo'])}, {s(r[k + '_hi'])}]"
row = lambda m, y: C[(C.model == m) & (C.outcome == y)].iloc[0]
k = lambda n: f"{int(n):,}".replace(",", "{,}")
M = {}
for n, m in (("All", "two judges"), ("Mid", "deciles 2 to 9 only"), ("NoThree", "without country, capital and sport"), ("Levels", "knowledge score as 11 levels")):
    for t, y in (("", "both"), ("Regex", "regex24")):
        r = row("regex, 20 short replies" if (n, t) == ("All", "Regex") else m, y); M[f"gx{n}{t}"], M[f"gx{n}{t}CI"] = s(r.b_obscurity), ci(r)
    M[f"gx{n}N"] = k(row(m, "both").n)
p, q = row("two judges", "both"), row("other abstention measure", "qwen")
M |= dict(gxKnow=s(p.b_knowledge), gxKnowCI=ci(p, "knowledge"), gxPredPop=f"{p.predicted_at_popularity_90th:.2f}", gxPredObs=f"{p.predicted_at_popularity_10th:.2f}", gxQwen=s(q.b_obscurity), gxQwenCI=ci(q),
          gxN=k(len(Q)), gxDropped=p.relations_dropped_constant, gxDroppedN=str(int((Q.prop == p.relations_dropped_constant).sum())),
          gxNoConv=str(int(row("knowledge score as 11 levels", "both").draws_not_converged)), gxNoConvRegex=str(int(row("knowledge score as 11 levels", "regex24").draws_not_converged)))
assert Q[Q.prop == p.relations_dropped_constant].both.max() == 0 and "xtAllN}{4{,}376}" in (P / "numbers_x2.tex").read_text() and M["gxN"] == "4{,}376"
(P / "numbers_x3.tex").write_text("% GENERATED by scripts/make_srw_v3.py from results/x3/*.csv\n" + "".join(f"\\newcommand{{\\{n}}}{{{v}}}\n" for n, v in M.items()), encoding="utf-8")

E = [
    ("\\small\\setlength{\\tabcolsep}{3pt}\n\\begin{tabular}{lrll}\n\\toprule\n& $n$ & Two judges & Regex \\\\", "\\small\\setlength{\\tabcolsep}{3pt}\n\\resizebox{\\columnwidth}{!}{%\n\\begin{tabular}{lrll}\n\\toprule\n& $n$ & Two judges & Regex \\\\"),
    ("\\bottomrule\n\\end{tabular}\n\\caption{Coefficient of obscurity", "\\bottomrule\n\\end{tabular}}\n\\caption{Coefficient of obscurity"),
    ("\\input{../numbers_x2.tex}", "\\input{../numbers_x2.tex}\n\\input{../numbers_x3.tex}"),
    (r"The effect of popularity holds across the whole popularity range (\xtAllN{} further questions).", r"The effect of popularity holds across the whole popularity range (\xtAllN{} further questions), and a second model, Gemma-2-9B-it, shows it on the same questions when the prompt invites abstaining."),
    (r"because their sizes depend on how the two variables are scaled (Appendix~\ref{app:range}).",
     "because their sizes depend on how the two variables are scaled (Appendix~\\ref{app:range}).\n\n\\paragraph{A Second Model.} We repeated this check on Gemma-2-9B-it with the same questions, asked with the prompt that invites abstaining because Gemma rarely says \\idk{} without it (Appendix~\\ref{app:other}); knowledge is Gemma's own, and the plan was recorded before the run. "
     "Obscurity again raises abstention: \\gxAll{} \\gxAllCI, \\gxMid{} \\gxMidCI{} without the extreme tenths and \\gxAllRegex{} \\gxAllRegexCI{} with the regex. Predicted abstention is \\gxPredPop{} at the 90th percentile of popularity and \\gxPredObs{} at the 10th. "
     "The prompts differ between the two models, so the sizes are not comparable. The popularity effect thus holds for Llama-3.1-8B-Instruct and Gemma-2-9B-it on PopQA."),
    (r"We study one model in depth, on one dataset; other models appear only in Figure~\ref{fig:dissociation}c and Appendix~\ref{app:other}.", r"We study one model in depth and a second in one check, under a prompt that invites abstaining, on one dataset; other models appear only in Figure~\ref{fig:dissociation}c and Appendix~\ref{app:other}."),
    ("\\midrule\nAll tenths & \\xtAllN &", "\\midrule\n\\multicolumn{4}{l}{\\emph{Llama-3.1-8B-Instruct}} \\\\\nAll tenths & \\xtAllN &"),
    ("Knowledge in 11 levels & \\xtLevelsN & \\xtLevels{} \\xtLevelsCI & \\xtLevelsRegex{} \\xtLevelsRegexCI \\\\\n",
     "Knowledge in 11 levels & \\xtLevelsN & \\xtLevels{} \\xtLevelsCI & \\xtLevelsRegex{} \\xtLevelsRegexCI \\\\\n\\midrule\n\\multicolumn{4}{l}{\\emph{Gemma-2-9B-it, inviting prompt}} \\\\\n"
     + "".join(f"{lab} & \\gx{n}N & \\gx{n}{{}} \\gx{n}CI & \\gx{n}Regex{{}} \\gx{n}RegexCI \\\\\n" for lab, n in (("All tenths", "All"), ("Tenths 2 to 9", "Mid"), ("Without three relations", "NoThree"), ("Knowledge in 11 levels", "Levels")))),
    (r"With the uncorrected labels of the Gemma judge the first two-judge entry is \xtOld{} \xtOldCI.}", r"With the uncorrected labels of the Gemma judge the first two-judge entry is \xtOld{} \xtOldCI. Gemma: the relation \gxDropped{} (\gxDroppedN{} questions) has no abstention and is dropped from the fits; \gxNoConv{} draws of the 11-level two-judge fit and \gxNoConvRegex{} of the regex fit did not converge and are dropped.}"),
    (r"The amendment replaced two pilot checks,", "\\begin{figure}[h]\n\\centering\n\\includegraphics[width=\\columnwidth]{../../results/x3/fig_x3_gradient.pdf}\n\\caption{As Figure~\\ref{fig:range}, for Gemma-2-9B-it with the prompt that invites abstaining.}\n\\label{fig:gemmarange}\n\\end{figure}\n\n"
     "For Llama, the amendment replaced two pilot checks,"),
    (r"The knowledge score and the paper's known/unknown labels come from the same forced-answer prompt and string grader.", r"The knowledge score and the paper's known/unknown labels come from the same forced-answer prompt and string grader. The Gemma run used the same questions, judges and analysis and needed no amendment; knowledge lowers abstention there too (\gxKnow{} \gxKnowCI). One judge, Gemma-2-27B, is from the tested model's family; with Qwen alone the obscurity coefficient is \gxQwen{} \gxQwenCI."),
]
t = (P / "srw/main_v2.tex").read_text(encoding="utf-8"); n0 = len(t.split())
for a, b in E:
    assert t.count(a) == 1, (t.count(a), a[:80])
    t = t.replace(a, b)
(P / "srw/main_v3.tex").write_text(t, encoding="utf-8")
pd.DataFrame(E, columns=["old", "new"]).to_csv(REPO / "results/x3/paper_srw_v3_changes.csv", index=False)
# static checks and expanded text
mac = {}
for f in ("numbers_v2.tex", "numbers_x2.tex", "numbers_x3.tex"):
    for l in (P / f).read_text(encoding="utf-8").splitlines():
        m = re.match(r"\\newcommand\{\\(\w+)\}\{(.*)\}(?:\s*%.*)?$", l)
        if m:
            assert m[1] not in mac, m[1]
            mac[m[1]] = m[2]
body = "\n".join(re.split(r"(?<!\\)%", l)[0] for l in t.splitlines())
print("undefined gx/xt macros:", sorted(m for m in set(re.findall(r"\\((?:gx|xt)[A-Za-z]+)", body)) if m not in mac), "| braces", body.count("{") - body.count("}"), "| $ even", len(re.findall(r"(?<!\\)\$", body)) % 2 == 0,
      "| env", sorted(re.findall(r"\\begin\{(\w+\*?)\}", body)) == sorted(re.findall(r"\\end\{(\w+\*?)\}", body)), "| undefined refs", sorted(set(re.findall(r"\\ref\{(.*?)\}", body)) - set(re.findall(r"\\label\{(.*?)\}", body))),
      "| duplicate labels", [x for x in set(re.findall(r"\\label\{(.*?)\}", body)) if body.count(f"\\label{{{x}}}") > 1], "| figures", [(P / "srw" / g).exists() or (P / "figures" / g).exists() for g in re.findall(r"\\includegraphics\[.*?\]\{(.*?)\}", body)], "| words", n0, "->", len(t.split()))
ex = re.sub(r"\\([A-Za-z]+)(\{\})?", lambda m: mac[m[1]].replace("$", "").replace("{,}", ",") if m[1] in mac else m[0], t)
for l in ex.splitlines():
    if l.startswith("\\paragraph{A Second Model") or "Gemma-2-9B-it, inviting" in l or re.match(r"(All tenths|Tenths 2|Without three|Knowledge in 11) ", l):
        print(l)
